 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    divider = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if divider is None:
        return out
    # The matching-colored marks above and below the divider define vertical
    # overlaps; fill those intervening columns with color 4.
    above_colors = {v for row in grid[:divider] for v in row if v not in (0, 2)}
    below_colors = {v for row in grid[divider + 1:] for v in row if v not in (0, 2)}
    common = above_colors & below_colors
    for color in common:
        top_cols = {c for row in grid[:divider] for c, v in enumerate(row) if v == color}
        bottom_cols = {c for row in grid[divider + 1:] for c, v in enumerate(row) if v == color}
        for c in top_cols & bottom_cols:
            for r in range(divider):
                if grid[r][c] == 0:
                    out[r][c] = 4
    return out

